-- History only. These are all in terminal states on purpose: a seeded
-- 'queued' row would be a job id that exists in Postgres and not in Redis,
-- and nothing would ever pick it up. (The worker's reconcile() does repair
-- that case on startup - try inserting one and watch it.)
INSERT INTO jobs (id, state, attempts, filename, content_type, src_bytes,
                  src_width, src_height, box_width, box_height,
                  out_width, out_height, last_error, created_at, updated_at) VALUES
 (1,'done',1,'graduation-group.jpg','image/jpeg',2411008,4000,3000,320,320,320,240,NULL,
     now() - interval '3 hours', now() - interval '3 hours' + interval '4 seconds'),
 (2,'done',1,'campus-gate.png','image/png',880640,1600,1200,640,640,640,480,NULL,
     now() - interval '2 hours', now() - interval '2 hours' + interval '2 seconds'),
 (3,'done',2,'lab-panorama.jpg','image/jpeg',5242880,8000,1000,320,320,320,40,NULL,
     now() - interval '90 minutes', now() - interval '90 minutes' + interval '11 seconds'),
 (4,'dead',3,'not-really-an-image.pdf','application/pdf',12044,NULL,NULL,320,320,NULL,NULL,
     'UnidentifiedImageError: cannot identify image file',
     now() - interval '40 minutes', now() - interval '38 minutes'),
 (5,'dead',3,'truncated-upload.png','image/png',311,NULL,NULL,200,200,NULL,NULL,
     'OSError: image file is truncated',
     now() - interval '20 minutes', now() - interval '18 minutes')
ON CONFLICT DO NOTHING;
SELECT setval('jobs_id_seq', (SELECT max(id) FROM jobs));

-- Give the three finished jobs a real stored image, so GET /jobs/1/result
-- returns a PNG on a fresh database rather than an apology.
UPDATE jobs SET out_data = decode('','base64') WHERE id=1 AND out_data IS NULL;
UPDATE jobs SET out_data = decode('','base64') WHERE id=2 AND out_data IS NULL;
